/// <summary>
/// Class is used to make copy of <c>GUPVendPriceAdmTable</c> records. Should be called from form GUPVendPriceAdm.
/// </summary>
internal final class GUPVendPriceAdmTableCopy
{
    private GUPVendPriceAdmTable        gupVendPriceAdmTableOrig;
    private FormDataSource              gupVendPriceAdmTable_ds;

    #OCCRetryCount

}

Method.Source:
public void new(GUPVendPriceAdmTable _journalTable, FormDataSource _formDatasource = null)
{
    // Load vendor list price, or reference will change with form datasource.
    this.gupVendPriceAdmTableOrig   = GUPVendPriceAdmTable::find(_journalTable.JournalNum);
    this.gupVendPriceAdmTable_ds    = _formDatasource;
}

public static void main(Args _args)
{
    if (_args && _args.record() && _args.record().TableId == tableNum(GUPVendPriceAdmTable))
    {
        Object gupVendPriceAdmTable_ds = FormDataUtil::getFormDataSource(_args.record());
        GUPVendPriceAdmTableCopy gupVendPriceAdmTableCopy = new GUPVendPriceAdmTableCopy(_args.record(), gupVendPriceAdmTable_ds);

        gupVendPriceAdmTableCopy.run(_args);
    }
    else
    {
        throw error(strFmt("@SYS27147", classStr(GUPVendPriceAdmTableCopy)));
    }
}

private void run(Args _args)
{
    GUPVendPriceAdmTable    gupVendPriceAdmTableNew;

    try
    {
        if (this.checkNumseqExists())
        {
            ttsbegin;
            gupVendPriceAdmTable_ds.create(true);
            gupVendPriceAdmTableNew = this.copyTable(gupVendPriceAdmTableOrig);
            gupVendPriceAdmTableNew	= gupVendPriceAdmTable_ds.cursor();
            gupVendPriceAdmTable_ds.write();
            this.createline(gupVendPriceAdmTableOrig.JournalNum, gupVendPriceAdmTableNew);
            ttscommit;
        }
        else
        {
            GUPVendPriceJournalNum	vendPriceJournalNum = this.getJournalNumFromDialog(gupVendPriceAdmTableOrig.JournalNum);
            if (vendPriceJournalNum)
            {
                ttsbegin;
                gupVendPriceAdmTableNew = this.copyTable(gupVendPriceAdmTableOrig);
                gupVendPriceAdmTableNew	= gupVendPriceAdmTable_ds.cursor();
                gupVendPriceAdmTableNew.JournalNum = vendPriceJournalNum;
                gupVendPriceAdmTableNew.insert();
                this.createline(gupVendPriceAdmTableOrig.JournalNum, gupVendPriceAdmTableNew);
                gupVendPriceAdmTable_ds.research(1);
                ttscommit;
            }
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

private GUPVendPriceAdmTable copyTable(GUPVendPriceAdmTable _gupVendPriceAdmTableOrig)
{
    GUPVendPriceAdmTable    gupVendPriceAdmTableNew;

    gupVendPriceAdmTableNew.ExportCurrentPrice		= _gupVendPriceAdmTableOrig.ExportCurrentPrice;
    gupVendPriceAdmTableNew.FromDate				= _gupVendPriceAdmTableOrig.FromDate;
    gupVendPriceAdmTableNew.ToDate					= _gupVendPriceAdmTableOrig.ToDate;
    gupVendPriceAdmTableNew.Status					= GUPDisabledEnabled::Disabled;

    return gupVendPriceAdmTableNew;
}

private void createline(GUPVendPriceJournalNum _GUPVendPriceJournalNumOrig, GUPVendPriceAdmTable _gupVendPriceAdmTableNew)
{
    GUPVendPriceAdmTrans    gupVendPriceAdmTransNew, gupVendPriceAdmTransOrig;

    while select gupVendPriceAdmTransOrig
            where gupVendPriceAdmTransOrig.JournalNum == _GUPVendPriceJournalNumOrig
    {
        gupVendPriceAdmTransNew.clear();
        gupVendPriceAdmTransNew.initfromGUPVendPriceAdmTrans(gupVendPriceAdmTransOrig);
        gupVendPriceAdmTransNew.initFromGUPVendPriceAdmTable(_gupVendPriceAdmTableNew);
        gupVendPriceAdmTransNew.insert();
    }
}

private GUPVendPriceJournalNum getJournalNumFromDialog(GUPVendPriceJournalNum _JourNum)
{
    Args						args = new Args();
    GUPVendPriceJournalNum		vendPriceJournalNum;

    args.parm(_JourNum);
    args.caller(this);
    args.name(formstr(GUPJournalIdDialog));

    FormRun	formRun = classFactory.formRunClass(Args);

    formRun.init();
    formRun.run();
    formRun.wait();

    if (formRun.closedOk())
    {
        vendPriceJournalNum = formRun.getJourId();
    }

    return vendPriceJournalNum;
}
